// from Homebrew, plus an assertions build of llc for the -debug-only=isel dumps. Do not edit by hand.

export interface CodeStage {
	id: string;
	label: string;
	/** The command or file the code came from. */
	tool: string;
	lang: string;
	code: string;
	/** [line index, tag]: lines to colour by the tag's colour. */
	marks: [number, string][];
	note: string;
}
export interface StageTag {
	tag: string;
	label: string;
}
export interface DagStage {
	id: string;
	label: string;
	/** Text dump from llc -debug-only=isel. */
	dump: string;
	note: string;
}
export interface LlcPass {
	name: string;
	phase: string;
	analysis: boolean;
	nvptx: boolean;
}

