export const dotIr: string =
	"define dso_local float @dot(ptr nofree noundef readonly captures(none) %0, ptr nofree noundef readonly captures(none) %1, i32 noundef %2) local_unnamed_addr #0 {\n  %4 = icmp sgt i32 %2, 0\n  br i1 %4, label %7, label %5\n\n5:                                                ; preds = %7, %3\n  %6 = phi float [ 0.000000e+00, %3 ], [ %16, %7 ]\n  ret float %6\n\n7:                                                ; preds = %3, %7\n  %8 = phi i32 [ %17, %7 ], [ 0, %3 ]\n  %9 = phi float [ %16, %7 ], [ 0.000000e+00, %3 ]\n  %10 = zext nneg i32 %8 to i64\n  %11 = getelementptr inbounds nuw [4 x i8], ptr %0, i64 %10\n  %12 = load float, ptr %11, align 4\n  %13 = getelementptr inbounds nuw [4 x i8], ptr %1, i64 %10\n  %14 = load float, ptr %13, align 4\n  %15 = fmul contract float %12, %14\n  %16 = fadd contract float %9, %15\n  %17 = add nuw nsw i32 %8, 1\n  %18 = icmp eq i32 %17, %2\n  br i1 %18, label %5, label %7\n}";

